style.css:
@-moz-document domain("roblox.com") {
/* Убираем стандартный фон */
    body, html {
        background: none !important;
        background-color: transparent !important;
    }

    /* Глобальный фон, который не перекрывается */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;
        background: url("https://i.imgur.com/xEKXubo.gif") no-repeat center center fixed;
        background-size: cover;
        z-index: -9999 !important; /* Отправляем фон максимально назад */
    }

    /* Делаем контейнеры полупрозрачными */
    .container, .content, .main-container, .page-content, 
    .section-content, .profile-container, .rbx-navbar, 
    .profile-header-content, .game-stats-container, 
    .chat-body, .chat-container, .chat-window, .rbx-tabs-horizontal, 
    .settings-container, .inventory-container, .game-page, 
    .store-card-footer, .store-container, .input-group {
        background: rgba(0, 0, 0, 0.5) !important; /* Затемняем контейнеры */
        backdrop-filter: blur(5px) !important; /* Добавляем эффект размытия */
        border-radius: 10px !important; /* Закругляем углы */
    }

    /* Меню и верхняя панель */
    .navbar, .header, .nav-menu, .top-bar, #navigation {
        background: rgba(20, 20, 20, 0.8) !important;
        border-bottom: 2px solid #888 !important;
    }

    /* Кнопки */
    button, .btn {
        background: rgba(100, 100, 100, 0.7) !important;
        border: 1px solid #ccc !important;
        color: white !important;
    }

    button:hover, .btn:hover {
        background: rgba(150, 150, 150, 0.8) !important;
    }

    /* Текст */
    * {
        color: #ffffff !important;
    }
}
